from __future__ import annotations

from datetime import date
from decimal import Decimal, ROUND_HALF_UP


def to_iso(yyyymmdd: str | None) -> str | None:
    """Convert a legacy YYYYMMDD date to ISO YYYY-MM-DD."""
    if yyyymmdd is None or yyyymmdd == "" or yyyymmdd == "00000000":
        return None
    if len(yyyymmdd) != 8 or not yyyymmdd.isdigit():
        raise ValueError("expected a YYYYMMDD date")
    parsed = date(int(yyyymmdd[:4]), int(yyyymmdd[4:6]), int(yyyymmdd[6:8]))
    return parsed.isoformat()


def from_iso(iso: str | None) -> str:
    """Convert an ISO YYYY-MM-DD date to legacy YYYYMMDD."""
    if iso is None or iso == "":
        return "00000000"
    if len(iso) != 10:
        raise ValueError("expected a YYYY-MM-DD date")
    parsed = date.fromisoformat(iso)
    return parsed.strftime("%Y%m%d")


def yn(char: str | None) -> bool:
    """Convert a legacy Y/N value to a boolean."""
    return char == "Y"


def to_minor_units(amount, currency: str | None) -> int:
    """Convert a legacy monetary amount to currency minor units."""
    if amount is None or amount == "":
        value = Decimal(0)
    else:
        value = Decimal(str(amount))

    code = "USD" if currency is None or currency == "" else currency
    quantum = Decimal("1") if code == "JPY" else Decimal("0.01")
    return int((value / quantum).quantize(Decimal("1"), rounding=ROUND_HALF_UP))
